const SHANGHAI_OFFSET=8*60*60*1000;
export function shanghaiParts(date=new Date()){const shifted=new Date(date.getTime()+SHANGHAI_OFFSET);return{date:shifted.toISOString().slice(0,10),minutes:shifted.getUTCHours()*60+shifted.getUTCMinutes()};}
export function shanghaiDate(date,minutes){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isInteger(minutes)||minutes<0||minutes>=1440)throw Error('请选择有效的日期和时间');const midnight=new Date(date+'T00:00:00+08:00');if(!Number.isFinite(midnight.getTime())||shanghaiParts(midnight).date!==date)throw Error('日期不存在');return new Date(midnight.getTime()+minutes*60000);}
export const clockLabel=minutes=>String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(Math.floor(minutes%60)).padStart(2,'0');
export function createParkClock(onChange){let state={...shanghaiParts(),live:true},lastMinute=-1;return{get state(){return{...state};},get dateTime(){return shanghaiDate(state.date,state.minutes);},set(date,minutes,live=false){shanghaiDate(date,minutes);state={date,minutes:Math.round(minutes),live};onChange(this.dateTime,this.state);},sync(){const p=shanghaiParts();this.set(p.date,p.minutes,true);},tick(){if(!state.live)return;const now=Date.now(),minute=Math.floor(now/60000);if(minute===lastMinute)return;lastMinute=minute;this.sync();}};}
